export async function loadBlocksConfig(s){const o=await fetch(s);if(!o.ok)throw new Error(`Failed to load Blocks config from ${s}: ${o.status}`);const c=await o.json();if(!c.subscribeKey)throw new Error("Invalid Blocks config: missing subscribeKey");return{publishKey:c.publishKey??"",subscribeKey:c.subscribeKey,blocksBackendUrl:c.blocksBackendUrl??""}}